KEYWORDS = {
    "fear": ["afraid","scared","fear","frightened","nervous"],
    "anxiety": ["anxious","anxiety","worried","worry","overthinking","stress","panic"],
    "sadness": ["sad","cry","crying","unhappy","down","broken"],
    "loneliness": ["lonely","alone","isolated","nobody","no one"],
    "anger": ["angry","mad","furious","annoyed","rage"],
    "friendship": ["friend","friends","friendship"],
    "conflict": ["argument","fight","conflict","fighting"],
    "forgiveness": ["forgive","forgiveness","guilt","mistake"],
    "gratitude": ["grateful","thankful","thank","appreciate"],
    "joy": ["happy","joy","joyful","excited","celebrate"],
    "motivation": ["motivation","motivated","give up","quit","keep going","hard"],
    "failure": ["failed","failure","messed up"],
    "school": ["school","homework","test","exam","grade","teacher"],
    "future": ["future","tomorrow","career","next year"],
    "decisions": ["decision","decide","choice","choose","should i"],
    "confusion": ["confused","confusing","don't know","unsure"],
    "trust": ["trust","believe"],
    "peace": ["peace","calm","relaxed","rest"],
    "tired": ["tired","exhausted","weary","drained"],
    "overwhelmed": ["overwhelmed","too much","burden"],
    "strength": ["strong","strength","weak","courage"],
    "hope": ["hope","hopeless","better"],
    "love": ["love","loving","relationship"],
    "kindness": ["kind","kindness","compassion"],
    "wisdom": ["wisdom","advice","guidance"],
    "help": ["help","struggling","need help"],
    "patience": ["patient","waiting","wait"],
    "change": ["change","new","moving","move","starting over"],
    "prayer": ["pray","prayer","praying"],
}

def find_verse(text, previous=None):
    text = text.lower()
    themes = []
    for theme, words in KEYWORDS.items():
        if any(word in text for word in words):
            themes.append(theme)

    if not themes:
        choices = [v for v in VERSES if v[0] != previous] or VERSES
        return random.choice(choices), []

    scored = []
    for verse in VERSES:
        ref, quote = verse
        score = sum(1 for theme in themes if any(w in quote.lower() for w in KEYWORDS[theme]))
        if ref == previous:
            score -= 20
        scored.append((score, random.random(), verse))

    scored.sort(key=lambda x: (x[0], x[1]), reverse=True)
    best = scored[0][0]
    options = [v for s, _, v in scored if s == best and v[0] != previous]
    return random.choice(options[:12] or [scored[0][2]]), themes[:3]

